    {'regulation_id': 'JGJ276-2012-3.0.21@no_people_on_suspended_load', 'scene_types': ['LIFTING_OPERATIONS'], 'risk_keys': ['NO_PEOPLE_ON_SUSPENDED_LOAD', 'JGJ276_2012_3_0_21_NO_PEOPLE_ON_SUSPENDED_LOAD'], 'risk_aliases': ['吊物站人', '载运人员', '吊起构件', '操作平台', '吊具承载对象及周边空间'], 'standard_name': '建筑施工起重吊装工程安全技术规范', 'standard_code': 'JGJ 276—2012', 'article': '第3.0.21；3.0.7条', 'clause_text': '3.0.21 严禁在吊起的构件上行走或站立,不得用起重机载运人员,不得在构件上堆放或悬挂零星物件。 3.0.7 登高梯子的上端应予固定,高空用的吊篮和临时工作台应绑扎牢靠。吊篮和工作台的脚手板应铺平 绑牢,严禁出现探头板。吊移操作平台时,平台上面严禁站人。', 'source_url': 'data/rulepack/rulepack_snapshot.json#JGJ276-2012-3.0.21@no_people_on_suspended_load', 'keywords': ['载运人员', '吊起构件', '操作平台'], 'judge_dimension': '起重机不得载人，吊起构件与吊移平台上不得站人', 'judge_boundary': {'compliant': '起重机吊运对象和承载范围完整可见，未载人，吊起构件或吊移平台上无人行走、站立。', 'non_compliant': '同图显示起重机载人，或人员站立、行走在吊起的构件或吊移平台上。', 'doubtful': '证据不足：无法确认起吊状态、人员承载关系或全部承载范围。'}, 'triggers': [{'trigger_id': 'LO-J276-260925-05', 'trigger_name': '吊具承载对象及周边空间', 'visibility_tag': '外观', 'recognition_mode': 'vlm_visual', 'observable_cues': ['吊钩或吊索与构件、平台或人员等承载对象的可见联系', '承载对象端部、表面或其下方区域的局部画面', '不要求溜绳、人员或零星物件存在，也不预判对象已悬空或人员违规']}], 'disposal_suggestion': '停止利用起重机载运人员，使人员离开吊起的构件和吊移中的操作平台。', 'rulepack_version': None},
